                G.removeLast(); // Remove from rear 

            // Add current element at rear of both deque 
            G.addLast(i); 
            S.addLast(i); 
        } 

        // Sum of minimum and maximum element of last window 
        sum += arr[S.peekFirst()] + arr[G.peekFirst()]; 

        return sum; 
    } 

